import numpy as np

def make_logprice(seed, n=1500):
    """Seeded log price: a random walk with drift, 0.04% a day on average, 1.2% daily sd."""
    rng = np.random.default_rng(seed)
    return np.log(100) + np.cumsum(0.0004 + 0.012 * rng.standard_normal(n))

def ffd_weights(d, threshold):
    """Weights w_0, w_1, ... kept while |w_k| >= threshold."""
    w, k = [1.0], 1
    while k < 100000:
        nxt = -w[-1] * (d - k + 1) / k
        if abs(nxt) < threshold:
            break
        w.append(nxt)
        k += 1
    return np.array(w)

