import numpy as np

def memory_kept(x, d):
    y = frac_diff(x, d)
    ok = ~np.isnan(y)
    return round(float(np.corrcoef(y[ok], x[ok])[0, 1]), 3)

def smallest_d(x, ds, stat_fn, cutoff):
    for d in ds:
        y = frac_diff(x, d)
        if stat_fn(y[~np.isnan(y)]) < cutoff:
            return d
    return None

