    """Variance ratio: var of k-day changes over k times var of 1-day changes."""
    y = np.asarray(y, dtype=float)
    y = y[~np.isnan(y)]
    return float(np.var(y[k:] - y[:-k]) / (k * np.var(y[1:] - y[:-1])))

